SELECT 
    SUM(QT_MAT_BAS) AS TOTAL_MATRICULAS_BÁSICA
FROM matriculas;

SELECT 
    SUM(CASE WHEN TP_LOCALIZACAO IN ('1', '4') THEN QT_MAT_BAS ELSE 0 END) AS MATRICULAS_TURMA_1_4
FROM matriculas;

SELECT NU_ANO_CENSO
FROM matriculas
WHERE NU_ANO_CENSO IN (SELECT MIN(NU_ANO_CENSO) FROM matriculas);

SELECT COUNT(DISTINCT CO_ENTIDADE) AS quantidade_escolas
FROM matriculas
WHERE QT_MAT_BAS = 0;

SELECT COUNT(DISTINCT CO_ENTIDADE) AS NUM_ESCOLAS
FROM matriculas
WHERE QT_MAT_BAS = 0;

SELECT SUM(QT_MAT_BAS) AS total_escolas_urbanas, SUM(QT_MAT_BAS - (QT_MAT_BAS - QT_MAT_BAS_INT)) AS total_escolas_rurais
FROM matriculas
WHERE TP_LOCALIZACAO = '2';

